from typing import Dict, List, Optional, Tuple, Union
import re
import numpy as np
from typing_extensions import Protocol
from pandas import DataFrame


class Similarity(Protocol):
    """Similarity function protocol."""


def parse_min_should_match(num_search_terms: int, spec: str) -> int:
    """Parse the minimum should match specification.

    Parameters
    ----------
    num_search_terms : int
        Number of search terms.
    spec : str
        Minimum should match specification.

    Returns
    -------
    int
        Minimum number of matches.
    """
    if spec == "":
        return num_search_terms
    elif spec.isdigit():
        return int(spec)
    elif spec == "1<":
        return 1
    elif spec == "<1":
        return num_search_terms
    else:
        raise ValueError("Invalid 'mm' spec. Expecting an integer.")


def parse_field_boosts(field_lists: List[str]) -> dict:
    """Parse Solr's qf, pf, pf2, pf3 field boosts."""
    if not field_lists:
        return {}

    out = {}
    carat_pattern = re.compile(r'\^')

    for field in field_lists:
        parts = carat_pattern.split(field)
        out[parts[0]] = None if len(parts) == 1 else float(parts[1])

    return out


def get_field(frame, field) -> SearchArray:
    if field not in frame.columns:
