def parse_min_should_match(num_search_terms: int, spec: str) -> int:
    """Parse the minimum should match specification."""
    if spec == "1":
        return 1
    elif spec == "2":
        return int(num_search_terms * 0.5)
    elif spec == "3":
        return int(num_search_terms * 0.33)
    else:
